static void mod_msconnector_merge_config_cpv(
        plugin_config * const config,
        const config_plugin_value_t * const cpv) {
    switch (cpv->k_id) {
      case 0: /* msconnector.enabled */
        config->enabled = cpv->v.u != 0U;
        break;
      case 1: /* msconnector.config-file */
        config->config_file = cpv->v.b;
        break;
      case 2: /* msconnector.expose-host-transaction-id */
        config->expose_host_transaction_id = cpv->v.u != 0U;
        break;
      case 3: /* msconnector.request-body-gate */
        config->request_body_gate = cpv->v.b;
        break;
      default:
        break;
    }
}

static void mod_msconnector_merge_config(
        plugin_config * const config,
        const config_plugin_value_t *cpv) {
    do {
        mod_msconnector_merge_config_cpv(config, cpv);
    } while ((++cpv)->k_id != -1);
}

SETDEFAULTS_FUNC(mod_msconnector_set_defaults) {
    static const config_plugin_keys_t keys[] = {
      { CONST_STR_LEN("msconnector.enabled"),
        T_CONFIG_BOOL,
        T_CONFIG_SCOPE_SERVER }
     ,{ CONST_STR_LEN("msconnector.config-file"),
        T_CONFIG_STRING,
        T_CONFIG_SCOPE_SERVER }
     ,{ CONST_STR_LEN("msconnector.expose-host-transaction-id"),
        T_CONFIG_BOOL,
        T_CONFIG_SCOPE_SERVER }
     ,{ CONST_STR_LEN("msconnector.request-body-gate"),
        T_CONFIG_STRING,
        T_CONFIG_SCOPE_SERVER }
     ,{ NULL, 0,
        T_CONFIG_UNSET,
        T_CONFIG_SCOPE_UNSET }
    };
    plugin_data * const p = p_d;
#ifndef LIGHTTPD_MSCONNECTOR_STREAM_HOOK_ABI_VERSION
    msconnector_request_mapper_contract request_contract;
    msconnector_response_mapper_contract response_contract;
#else
    msconnector_body_mode request_body_mode;
    msconnector_body_mode response_body_mode;
#endif
    char error[512] = "";

    if (!config_plugin_values_init(srv, p, keys, "mod_msconnector")) {
        return HANDLER_ERROR;
    }
    if (p->nconfig > 0 && p->cvlist->v.u2[1]) {
        const config_plugin_value_t *cpv =
            p->cvlist + p->cvlist->v.u2[0];
        if (cpv->k_id != -1) {
            mod_msconnector_merge_config(&p->defaults, cpv);
        }
    }
    if (!p->defaults.enabled) {
        return HANDLER_GO_ON;
    }
    if (p->defaults.config_file == NULL ||
        buffer_is_blank(p->defaults.config_file)) {
        log_error(
            srv->errh,
            __FILE__,
            __LINE__,
            "msconnector.config-file is required when msconnector.enabled is true");
        return HANDLER_ERROR;
    }
    if (!msconnector_runtime_config_check(
            "lighttpd",
            p->defaults.config_file->ptr,
            error,
            sizeof(error))) {
        log_error(
            srv->errh,
            __FILE__,
            __LINE__,
            "msconnector runtime config check failed: %s",
            error[0] == '\0' ? "unknown error" : error);
        return HANDLER_ERROR;
    }
    if (!msconnector_runtime_create(
            "lighttpd",
            p->defaults.config_file->ptr,
            &p->runtime,
            error,
            sizeof(error))) {
        log_error(
            srv->errh,
            __FILE__,
            __LINE__,
            "msconnector runtime creation failed: %s",
            error[0] == '\0' ? "unknown error" : error);
        return HANDLER_ERROR;
    }
    if (!msconnector_runtime_set_event_integration_mode(
            p->runtime, MSCONNECTOR_LIGHTTPD_EVENT_INTEGRATION_MODE)) {
        log_error(
            srv->errh,
            __FILE__,
            __LINE__,
            "msconnector runtime could not set %s event integration mode",
            MSCONNECTOR_LIGHTTPD_EVENT_INTEGRATION_MODE);
        msconnector_runtime_destroy(&p->runtime);
        return HANDLER_ERROR;
    }

    {
        const char *solution_id =
#ifdef LIGHTTPD_MSCONNECTOR_STREAM_HOOK_ABI_VERSION
            "lighttpd-patched";
#else
            "lighttpd-stock";
#endif
        const msconnector_transaction_profile *profile =
            msconnector_profile_registry_find(solution_id);
        if (profile == NULL ||
            msconnector_transaction_profile_phase_route(profile,
                MSCONNECTOR_PHASE_REQUEST_HEADERS) !=
                MSCONNECTOR_TRANSACTION_PHASE_ROUTE_DIRECT ||
            msconnector_transaction_profile_phase_route(profile,
                MSCONNECTOR_PHASE_RESPONSE_HEADERS) !=
                MSCONNECTOR_TRANSACTION_PHASE_ROUTE_DIRECT) {
            log_error(srv->errh, __FILE__, __LINE__,
                "lighttpd transaction profile is missing direct P1/P3 support");
            msconnector_runtime_destroy(&p->runtime);
            return HANDLER_ERROR;
        }
        if (!msconnector_runtime_set_transaction_profile(p->runtime, profile)) {
            log_error(srv->errh, __FILE__, __LINE__,
                "lighttpd transaction profile injection failed");
            msconnector_runtime_destroy(&p->runtime);
            return HANDLER_ERROR;
        }
    }

#ifdef LIGHTTPD_MSCONNECTOR_STREAM_HOOK_ABI_VERSION
    request_body_mode = msconnector_runtime_request_body_mode(p->runtime);
    response_body_mode = msconnector_runtime_response_body_mode(p->runtime);
    if (request_body_mode == MSCONNECTOR_BODY_MODE_BUFFERED ||
        (response_body_mode != MSCONNECTOR_BODY_MODE_NONE &&
         response_body_mode != MSCONNECTOR_BODY_MODE_STREAMING)) {
        log_error(
            srv->errh,
            __FILE__,
            __LINE__,
            "patched lighttpd module requires request_body_mode=none or streaming and response_body_mode=none or streaming");
        msconnector_runtime_destroy(&p->runtime);
        return HANDLER_ERROR;
    }
    if (request_body_mode == MSCONNECTOR_BODY_MODE_STREAMING &&
        (p->defaults.request_body_gate == NULL ||
         buffer_is_blank(p->defaults.request_body_gate) ||
         strcmp(p->defaults.request_body_gate->ptr, "pre-upstream") != 0)) {
        log_error(
            srv->errh,
            __FILE__,
            __LINE__,
            "patched lighttpd request_body_mode=streaming requires msconnector.request-body-gate=pre-upstream");
        msconnector_runtime_destroy(&p->runtime);
        return HANDLER_ERROR;
    }
    if (request_body_mode != MSCONNECTOR_BODY_MODE_STREAMING &&
        p->defaults.request_body_gate != NULL &&
        !buffer_is_blank(p->defaults.request_body_gate)) {
        log_error(
            srv->errh,
            __FILE__,
            __LINE__,
            "msconnector.request-body-gate is only valid with request_body_mode=streaming");
        msconnector_runtime_destroy(&p->runtime);
        return HANDLER_ERROR;
    }
    p->request_body_hooks_enabled =
        request_body_mode == MSCONNECTOR_BODY_MODE_STREAMING;
    p->response_body_hooks_enabled =
        response_body_mode == MSCONNECTOR_BODY_MODE_STREAMING;
#else
    msconnector_runtime_request_contract(p->runtime, &request_contract);
    msconnector_runtime_response_contract(p->runtime, &response_contract);
    if (request_contract.request_body != MSCONNECTOR_MAPPER_UNSUPPORTED ||
        response_contract.response_body != MSCONNECTOR_MAPPER_UNSUPPORTED) {
        log_error(
            srv->errh,
            __FILE__,
            __LINE__,
            "stock lighttpd module requires request_body_mode=none and response_body_mode=none; rebuild lighttpd with the version-contract-selected streaming-hook patch for request streaming");
        msconnector_runtime_destroy(&p->runtime);
        return HANDLER_ERROR;
    }
#endif

    p->total_header_limit =
        msconnector_runtime_total_header_limit(p->runtime);
    p->header_count_limit =
        msconnector_runtime_header_count_limit(p->runtime);

    return HANDLER_GO_ON;
}

static handler_ctx *handler_ctx_create(plugin_data * const p) {
    handler_ctx * const ctx = calloc(1U, sizeof(*ctx));
    if (ctx == NULL) {
        return NULL;
    }
    lighttpd_modsecurity_map_storage_init(&ctx->request_storage);
    lighttpd_modsecurity_map_storage_init(&ctx->response_storage);
    ++p->host_transaction_counter;
    if (p->host_transaction_counter == 0U) {
        ++p->host_transaction_counter;
    }
    (void)snprintf(
        ctx->host_request_id,
        sizeof(ctx->host_request_id),
        "lighttpd-%ld-%lu",
        (long)getpid(),
        p->host_transaction_counter);
    return ctx;
}

static void handler_ctx_destroy(handler_ctx **ctx_ptr) {
    handler_ctx *ctx;
    if (ctx_ptr == NULL || *ctx_ptr == NULL) {
        return;
    }
    ctx = *ctx_ptr;
    if (ctx == &mod_msconnector_failed_context) {
        *ctx_ptr = NULL;
        return;
    }
    msconnector_runtime_transaction_destroy(&ctx->transaction);
    lighttpd_modsecurity_map_storage_free(&ctx->request_storage);
    lighttpd_modsecurity_map_storage_free(&ctx->response_storage);
    free(ctx);
    *ctx_ptr = NULL;
}

static handler_t mod_msconnector_error_response(
        request_st * const r,
        const msconnector_runtime * const runtime,
        msconnector_error_code code) {
    int status = msconnector_runtime_error_http_status(runtime, code);
    if (status < 400 || status > 599) {
        status = 500;
    }
    return http_status_set_err(r, status);
}

/* Preserve the terminal adapter state until request reset; a retry must not
 * create a fresh transaction or select a second response after a failure. */
static handler_t mod_msconnector_fail_request(
        request_st *r,
        const msconnector_runtime *runtime,
        handler_ctx *ctx,
        msconnector_error_code code) {
    msconnector_error error;
    handler_t result;
    if (ctx != NULL && ctx->technical_failed) return HANDLER_ERROR;
    if (ctx != NULL) ctx->technical_failed = 1;
    msconnector_error_init(&error);
    if (ctx != NULL && ctx->transaction != NULL) {
        (void)msconnector_runtime_transaction_set_response_commit_state_checked(
            ctx->transaction, r->write_queue.bytes_out > 0,
            r->resp_header_len > 0U &&
                r->write_queue.bytes_out > (off_t)r->resp_header_len, &error);
        (void)msconnector_runtime_transaction_fail(ctx->transaction,
            MSCONNECTOR_TRANSACTION_ERROR_CONNECTOR, &error);
    }
    /* Even a partial header owns the output.  HANDLER_ERROR stops the host
     * path; it does not assert that a transport abort was observed. */
    if (r->write_queue.bytes_out > 0 ||
        (ctx != NULL && ctx->host_response_attempted)) return HANDLER_ERROR;
    result = mod_msconnector_error_response(r, runtime, code);
    if (result != HANDLER_ERROR && ctx != NULL && ctx->transaction != NULL) {
        if (msconnector_runtime_transaction_record_failure_host_action(
                ctx->transaction, r->http_status, 0, &error) != 1)
            return HANDLER_ERROR;
    }
    return result;
}

static handler_t mod_msconnector_apply_decision(
        request_st * const r,
        plugin_data * const p,
        handler_ctx * const ctx,
        const msconnector_decision * const decision) {
    handler_t result;
    msconnector_error runtime_error;
    int status;
    if (ctx != NULL && (ctx->technical_failed || ctx->api_failed)) {
        return HANDLER_ERROR;
    }
    if (!msconnector_decision_is_disruptive(decision)) {
        return HANDLER_GO_ON;
    }
    status = msconnector_decision_http_status(decision);
    if (status < 400 || status > 599) {
        status = 403;
    }
    result = http_status_set_err(r, status);
    if (ctx != NULL) ctx->host_response_attempted = 1;
    if (result == HANDLER_ERROR) {
        return mod_msconnector_fail_request(r, p->runtime, ctx,
            MSCONNECTOR_ERROR_HOST_API_FAILURE);
    }

    /*
     * lighttpd applies every currently supported disruptive intervention as
     * an error response.  Record that actual host action only after
     * http_status_set_err() has selected the client-visible status.  This is
     * deliberately distinct from the Common decision event, which records
     * the rule engine's requested action before a host can apply it.
     */
    if (result != HANDLER_ERROR && ctx != NULL && ctx->transaction != NULL) {
        msconnector_error_init(&runtime_error);
        if (msconnector_runtime_transaction_record_host_action(
                ctx->transaction,
                decision,
                MSCONNECTOR_DECISION_ACTION_DENY,
                r->http_status,
                "http_status",
                0,
                &runtime_error) != 1) {
            log_error(
                r->conf.errh,
                __FILE__,
                __LINE__,
                "msconnector host-action event was not recorded: %s",
                msconnector_error_code_name(runtime_error.code));
            return mod_msconnector_fail_request(r, p->runtime, ctx, runtime_error.code);
        }
    }
    (void)p;
    return result;
}

/*
 * These response-header helpers are shared by the Stock and Patched host
 * paths.  They must remain outside the stream-hook ABI guard: Stock invokes
 * mod_msconnector_emit_host_transaction_id() from its response-start hook,
 * while only the entity-body callbacks below require the patched ABI.
 */
static int mod_msconnector_response_headers_committed(
        const request_st *r) {
    return r != NULL && r->resp_header_len > 0U &&
        r->write_queue.bytes_out >= (off_t)r->resp_header_len;
}

/*
 * The host transaction ID is created by handler_ctx_create(), never derived
 * from request metadata, and takes precedence over the legacy fallback
 * transaction_id_header.  A private runtime harness can opt in to returning
 * that host-generated value on the actual response so it can correlate one
 * wire exchange with Common Runtime evidence.  This is deliberately disabled
 * by default: the serial includes process-local information and is not a
 * general-purpose public response header.
 *
 * Use response_set rather than response_insert.  In particular, an upstream
 * response or a client-controlled request header bearing this name must not
 * yield a second or forged response value.  This function is called only
 * after the real response has been mapped into Common Runtime, so the
 * evidence header cannot influence ModSecurity response evaluation.
 */
static int mod_msconnector_emit_host_transaction_id(
        request_st * const r,
        const plugin_data * const p,
        const handler_ctx * const ctx) {
    size_t transaction_id_size;

    if (p == NULL || !p->defaults.expose_host_transaction_id) {
        return 1;
    }
    if (r == NULL || ctx == NULL || ctx->host_request_id[0] == '\0') {
        return 0;
    }
    if (mod_msconnector_response_headers_committed(r)) {
        log_error(
            r->conf.errh,
            __FILE__,
            __LINE__,
            "msconnector evidence host transaction header would be emitted after response commit");
        return 0;
    }
    transaction_id_size = strlen(ctx->host_request_id);
    if (transaction_id_size >= sizeof(ctx->host_request_id)) {
        log_error(
            r->conf.errh,
            __FILE__,
            __LINE__,
            "msconnector host transaction identifier is not bounded");
        return 0;
    }
    http_header_response_set(
        r,
        HTTP_HEADER_OTHER,
        CONST_STR_LEN("X-Msconnector-Host-Transaction-Id"),
        ctx->host_request_id,
        (uint32_t)transaction_id_size);
    return 1;
}

